import{_ as a,c as l,o as e,ag as t}from"./chunks/framework.D6L8gzMI.js";const p=JSON.parse('{"title":"04-02","description":"","frontmatter":{"title":"04-02"},"headers":[],"relativePath":"review/4-2.md","filePath":"review/4-2.md","lastUpdated":1743572046000}'),s={name:"review/4-2.md"};function o(r,i,h,n,d,u){return e(),l("div",null,i[0]||(i[0]=[t('<h1 id="知识点" tabindex="-1">知识点 <a class="header-anchor" href="#知识点" aria-label="Permalink to &quot;知识点&quot;">​</a></h1><h2 id="sql-优化实践和思考点" tabindex="-1">SQL 优化实践和思考点 <a class="header-anchor" href="#sql-优化实践和思考点" aria-label="Permalink to &quot;SQL 优化实践和思考点&quot;">​</a></h2><ul><li>索引优化：创建合理的索引（如覆盖索引、前缀索引），避免全表扫描。</li><li>查询优化：使用 EXPLAIN 分析执行计划，避免 SELECT *，优化 JOIN。</li><li>分库分表：对大表进行水平或垂直拆分，提高查询效率。</li><li>缓存：利用 Redis、Memcached 缓存热点数据，减少数据库压力。</li><li>连接池：使用数据库连接池，如 HikariCP，提高并发性能。</li></ul><h2 id="事务实现原理" tabindex="-1">事务实现原理 <a class="header-anchor" href="#事务实现原理" aria-label="Permalink to &quot;事务实现原理&quot;">​</a></h2><p>事务（Transaction）基于 ACID（原子性、一致性、隔离性、持久性）：</p><ul><li>原子性（Atomicity）：通过 Undo Log 记录回滚信息。</li><li>一致性（Consistency）：事务前后数据库状态保持一致。</li><li>隔离性（Isolation）：通过 MVCC（多版本并发控制）或锁机制隔离不同事务。</li><li>持久性（Durability）：依靠 Redo Log 确保事务提交后不会丢失。</li></ul><h2 id="redo-log-工作机制" tabindex="-1">Redo Log 工作机制 <a class="header-anchor" href="#redo-log-工作机制" aria-label="Permalink to &quot;Redo Log 工作机制&quot;">​</a></h2><p><strong>作用：</strong> 保证事务的持久性（D in ACID）。</p><p><strong>写入方式：</strong></p><ol><li>事务执行时，先写入 Redo Log（WAL 机制）。</li><li>Redo Log 写入磁盘后，事务才算提交（避免宕机丢失）。</li><li>后续通过 Checkpoint 机制将数据刷入数据页（数据最终落盘）。</li></ol><h2 id="协程数量如何确定" tabindex="-1">协程数量如何确定 <a class="header-anchor" href="#协程数量如何确定" aria-label="Permalink to &quot;协程数量如何确定&quot;">​</a></h2><ul><li>I/O 密集型任务：可以开大量协程（取决于数据库连接数、网络 I/O）。</li><li>CPU 密集型任务：协程数量 ≈ CPU 核心数，避免 CPU 过度切换。</li><li>内存限制：协程栈通常较小（如 Golang 默认 2KB），但过多仍可能导致 OOM。</li></ul><h2 id="cpu-密集型任务使用协程是否有效" tabindex="-1">CPU 密集型任务使用协程是否有效 <a class="header-anchor" href="#cpu-密集型任务使用协程是否有效" aria-label="Permalink to &quot;CPU 密集型任务使用协程是否有效&quot;">​</a></h2><ul><li>协程本质是用户态线程，适合 I/O 密集型任务。</li><li>CPU 密集型任务需要占用 CPU，使用协程无法减少计算量。</li><li>解决方案： <ol><li>使用 runtime.GOMAXPROCS 充分利用多核 CPU（Go）。</li><li>采用多进程并行计算（Python/Rust）。</li></ol></li></ul><h2 id="协程是跨线程的吗" tabindex="-1">协程是跨线程的吗 <a class="header-anchor" href="#协程是跨线程的吗" aria-label="Permalink to &quot;协程是跨线程的吗&quot;">​</a></h2><ul><li>Go：Goroutine 由调度器 GPM 机制分配，可以跨线程执行。</li><li>Python asyncio：协程运行在单线程内，不跨线程。</li><li>Rust tokio：协程可调度到不同线程执行。</li></ul><h2 id="多线程执行协程会引入资源竞争问题吗" tabindex="-1">多线程执行协程会引入资源竞争问题吗 <a class="header-anchor" href="#多线程执行协程会引入资源竞争问题吗" aria-label="Permalink to &quot;多线程执行协程会引入资源竞争问题吗&quot;">​</a></h2><p>是的，如果协程访问共享资源（如全局变量、数据库连接），可能导致竞争。</p><p><strong>解决方案：</strong></p><ul><li>锁（Mutex、读写锁）。</li><li>Channel 进行线程间通信（如 Go chan、Rust mpsc）。</li><li>事务隔离 避免数据库竞态。</li></ul><h2 id="本地缓存和-redis-一致性保证" tabindex="-1">本地缓存和 Redis 一致性保证 <a class="header-anchor" href="#本地缓存和-redis-一致性保证" aria-label="Permalink to &quot;本地缓存和 Redis 一致性保证&quot;">​</a></h2><p><strong>缓存更新策略：</strong></p><ul><li>写后更新：数据变更时，更新 Redis 缓存。</li><li>失效策略：删除缓存，等待下一次查询自动加载。</li><li>双写不一致：可使用消息队列（Kafka）异步更新 Redis。</li></ul><h2 id="多机本地缓存一致性方案" tabindex="-1">多机本地缓存一致性方案 <a class="header-anchor" href="#多机本地缓存一致性方案" aria-label="Permalink to &quot;多机本地缓存一致性方案&quot;">​</a></h2><ul><li>基于消息队列：数据变更时广播更新。</li><li>基于分布式一致性协议（如 etcd、Zookeeper）。</li><li>Redis 作为缓存协调中心，所有实例查询 Redis 共享缓存。</li></ul><h2 id="redis-高性能原理" tabindex="-1">Redis 高性能原理 <a class="header-anchor" href="#redis-高性能原理" aria-label="Permalink to &quot;Redis 高性能原理&quot;">​</a></h2><ul><li>单线程模型（避免上下文切换）。</li><li>高效数据结构（如 ZipList、SkipList）。</li><li>持久化方式优化（AOF/快照）。</li><li>Pipeline 批量处理（减少 RTT）。</li></ul><h2 id="redis-多线程-vs-单线程争议" tabindex="-1">Redis 多线程 vs 单线程争议 <a class="header-anchor" href="#redis-多线程-vs-单线程争议" aria-label="Permalink to &quot;Redis 多线程 vs 单线程争议&quot;">​</a></h2><ul><li>Redis 6.0 引入多线程（用于 I/O 处理）。</li><li>数据操作仍是单线程（避免锁竞争）。</li><li>适用于 大 key 删除、慢查询优化。</li></ul><h2 id="bitmap-做用户签到的劣势" tabindex="-1">BitMap 做用户签到的劣势 <a class="header-anchor" href="#bitmap-做用户签到的劣势" aria-label="Permalink to &quot;BitMap 做用户签到的劣势&quot;">​</a></h2><ul><li>只能记录是否签到，无法存储其他信息。</li><li>不可扩展性：固定长度（按天数预分配）。</li><li>查询不灵活：不支持复杂查询，如时间段统计。</li></ul><h2 id="redis-集群持久化和备份机制" tabindex="-1">Redis 集群持久化和备份机制 <a class="header-anchor" href="#redis-集群持久化和备份机制" aria-label="Permalink to &quot;Redis 集群持久化和备份机制&quot;">​</a></h2><ul><li>RDB（快照）：定期保存整个数据集。</li><li>AOF（日志）：记录每次写操作，支持重放。</li><li>主从复制：数据多机备份，防止单点故障。</li></ul><h2 id="key-分片策略" tabindex="-1">Key 分片策略 <a class="header-anchor" href="#key-分片策略" aria-label="Permalink to &quot;Key 分片策略&quot;">​</a></h2><ul><li>Hash 分片（如一致性哈希）。</li><li>Range 分片（按 key 前缀分库）。</li><li>哈希槽分片（Redis Cluster 采用 16384 个槽）。</li></ul><h2 id="redis-集群槽位数量设计" tabindex="-1">Redis 集群槽位数量设计 <a class="header-anchor" href="#redis-集群槽位数量设计" aria-label="Permalink to &quot;Redis 集群槽位数量设计&quot;">​</a></h2><ul><li>固定 16384 槽，基于 CRC16 取模分配到不同节点。</li><li>节点扩容/缩容时，槽会重新分配。</li></ul><h2 id="c-多态实现原理" tabindex="-1">C++ 多态实现原理 <a class="header-anchor" href="#c-多态实现原理" aria-label="Permalink to &quot;C++ 多态实现原理&quot;">​</a></h2><ul><li>通过 虚函数表（vtable） 实现。</li><li>每个对象持有 虚表指针（vptr） 指向类的 vtable。</li></ul><h2 id="c-编译生成可执行文件过程" tabindex="-1">C++ 编译生成可执行文件过程 <a class="header-anchor" href="#c-编译生成可执行文件过程" aria-label="Permalink to &quot;C++ 编译生成可执行文件过程&quot;">​</a></h2><ul><li>预处理：宏展开、头文件展开。</li><li>编译：生成 .o 目标文件。</li><li>汇编：转换为机器码。</li><li>链接：合并库、符号解析，生成可执行文件。</li></ul><h2 id="多进程-多线程适用场景" tabindex="-1">多进程/多线程适用场景 <a class="header-anchor" href="#多进程-多线程适用场景" aria-label="Permalink to &quot;多进程/多线程适用场景&quot;">​</a></h2><ul><li>多进程：进程间隔离（如 Web 服务器）。</li><li>多线程：共享内存（如数据库连接池）。</li></ul><h2 id="nginx-采用多进程还是多线程" tabindex="-1">Nginx 采用多进程还是多线程 <a class="header-anchor" href="#nginx-采用多进程还是多线程" aria-label="Permalink to &quot;Nginx 采用多进程还是多线程&quot;">​</a></h2><ul><li>多进程模型，防止单个进程崩溃影响整体。</li></ul><h2 id="高性能网关设计方案" tabindex="-1">高性能网关设计方案 <a class="header-anchor" href="#高性能网关设计方案" aria-label="Permalink to &quot;高性能网关设计方案&quot;">​</a></h2><ul><li>异步非阻塞（如 Nginx、Envoy）。</li><li>负载均衡（LVS、Consistent Hash）。</li><li>缓存优化（CDN、Redis）。</li></ul><h2 id="进程间通信最快方式" tabindex="-1">进程间通信最快方式 <a class="header-anchor" href="#进程间通信最快方式" aria-label="Permalink to &quot;进程间通信最快方式&quot;">​</a></h2><ul><li>共享内存（shm）最快，避免数据拷贝。</li></ul><h2 id="https-改进与性能代价" tabindex="-1">HTTPS 改进与性能代价 <a class="header-anchor" href="#https-改进与性能代价" aria-label="Permalink to &quot;HTTPS 改进与性能代价&quot;">​</a></h2><ul><li>改进：TLS1.3 减少握手时间。</li><li>代价：加密/解密耗费 CPU。</li></ul><h2 id="常用-linux-命令" tabindex="-1">常用 Linux 命令 <a class="header-anchor" href="#常用-linux-命令" aria-label="Permalink to &quot;常用 Linux 命令&quot;">​</a></h2><ul><li><code>top</code>、<code>ps</code>、<code>lsof</code>、<code>df</code>、<code>netstat</code>。</li></ul><h2 id="高-cpu-进程定位" tabindex="-1">高 CPU 进程定位 <a class="header-anchor" href="#高-cpu-进程定位" aria-label="Permalink to &quot;高 CPU 进程定位&quot;">​</a></h2><ul><li><code>top</code> → <code>ps -eo pid,comm,%cpu --sort=-%cpu</code>。</li></ul><h2 id="pid-生成机制" tabindex="-1">PID 生成机制 <a class="header-anchor" href="#pid-生成机制" aria-label="Permalink to &quot;PID 生成机制&quot;">​</a></h2><ul><li>按序递增，超过上限回绕。</li></ul><h2 id="查找目录下最大的-10-个文件" tabindex="-1">查找目录下最大的 10 个文件 <a class="header-anchor" href="#查找目录下最大的-10-个文件" aria-label="Permalink to &quot;查找目录下最大的 10 个文件&quot;">​</a></h2><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">du </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ah </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sort </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rh </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> head </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span></span></code></pre></div>',59)]))}const k=a(s,[["render",o]]);export{p as __pageData,k as default};
